__NUXT_JSONP__("/desarrollo-sostenible/eventos/la_adaptacion_climatica_requiere_un_enfoque_incluyente_y_accesible", (function(a,b,c,d,e){return {data:[{post:{slug:"la_adaptacion_climatica_requiere_un_enfoque_incluyente_y_accesible",title:"La adaptación climática requiere un enfoque incluyente y accesible",date:"2025-03-11T18:59:16.519Z",img:"https:\u002F\u002Fucarecdn.com\u002F00636e24-4856-4d8a-82e6-7183e462155d\u002F","img-alt":"Néstor Genis Ethos",autor:"Ethos",category:"desarrollo-sostenible",extracto:"La adaptación al cambio climático requiere garantizar información accesible para todas las personas, promover procesos de largo plazo, fortalecer el ecosistema de organizaciones locales e incorporar enfoques inclusivos, dijo Néstor Genis, coordinador de Inclusión y Desarrollo Sostenible en Ethos, en el 6° Congreso Internacional de Gestión Integral del Riesgo y Resiliencia.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Para impulsar la adaptación al cambio climático, se requiere garantizar información accesible para todas las personas, promover procesos de largo plazo, fortalecer el ecosistema de organizaciones locales e incorporar enfoques inclusivos para construir verdaderas capacidades de resiliencia."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Así lo enfatizó Néstor Genis, coordinador de Inclusión y Desarrollo Sostenible en Ethos, en el panel ‘Impactos del cambio climático en comunidades urbanas y rurales’, del 6° Congreso Internacional de Gestión Integral del Riesgo y Resiliencia, organizado por la Secretaría de Gestión Integral de Riesgos y Protección Civil de la Ciudad de México (SGIRPC)."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Mencionó que la carencia de datos recientes dificulta la comprensión de la vulnerabilidad de las comunidades y la formulación de estrategias de adaptación efectivas, por ello, puntualizó que “necesitamos datos actualizados y procesos de socialización que permitan a las comunidades participar en la generación de información, apropiarse del conocimiento y colaborar en la creación de soluciones ante el cambio climático”."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"También agregó que se requiere invertir en acciones de largo plazo, que trasciendan financiamientos de uno o dos años o ciclos de las administraciones gubernamentales, pues la adaptación al cambio climático no se construye de un día para otro. “Todo proyecto debe considerar, desde su diseño, mecanismos que aseguren su continuidad y escalabilidad progresiva”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sobre el ecosistema de actores clave, consideró que la reducción de fondos en los últimos años ha limitado la capacidad de muchas organizaciones para promover medidas de adaptación al cambio climático. Ante ello, es vital apoyar a la sociedad civil y a los actores locales con recursos y capacitación para que lideren la adaptación en sus comunidades."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y finalmente, recordó que sin inclusión no hay resiliencia, así que se debe considerar siempre un enfoque interseccional en todas las actividades enfocadas a la adaptación al cambio climático. Pero es necesario “contemplar enfoques culturalmente sensibles que faciliten la incorporación progresiva y segura de las mujeres en los espacios de decisión, minimizando riesgos y fomentando la aceptación comunitaria”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En este panel también participaron como ponentes Mark McCarthy, coordinador de la Unidad de Migración, Medio Ambiente y Cambio Climático; Raúl Francisco Pineda López, director general del Centro de Capacitación en Cuencas A.C; Enrique Muñoz López, profesor del Colegio de Geografía de la UNAM y del Instituto Interamericano para la Investigación del Cambio Global; y Mauricio Hernández Ramírez, líder de Proyectos Estratégicos y Cooperación Internacional de la SGIRPC."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fla_adaptacion_climatica_requiere_un_enfoque_incluyente_y_accesible",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-04-23T06:21:15.373Z")));